#!/usr/bin/env bash
# ChromeX Enrichment V4 — generated by scripts/build_v4_installer.py.
# Reviewable, self-contained installer; V3 remains on its existing service/port.
set -Eeuo pipefail
umask 077

usage() {
  cat <<'HELP'
ChromeX Enrichment V4 (Ubuntu 24.04+ / Python 3.12+)
  bash EnrichmentV4.sh --extract ./v4-source  # offline; no root or installation
  sudo bash EnrichmentV4.sh                  # install isolated service on 127.0.0.1:8001
Optional install environment: APP_DIR, APP_PORT, COMPANIES_HOUSE_API_KEY,
ENRICHMENT_API_KEY, CRAWLER_USER_AGENT. Default search is local with no paid API.
Optional search: SEARCH_PROVIDER=searxng and SEARXNG_URL.
Optional browser discovery: see SEARCH-OPTIONS.md and deploy/scrapling/setup.sh.
Existing /etc/chromex-enrichment-v4.env is preserved on upgrades.
HELP
}
extract_payload() {
  python3 - "$0" "$1" <<'PY'
import base64, hashlib, io, pathlib, sys, zipfile
script = pathlib.Path(sys.argv[1]).read_text()
marker = '__V4_PAYLOAD_BELOW__' + '\n'
payload = base64.b64decode(script.rsplit(marker, 1)[1])
expected = 'd6af45de9d48505f9275bb8c62da7bb980f930cb0e86bd15933833f599cfe8c0'
if hashlib.sha256(payload).hexdigest() != expected:
    raise SystemExit('Installer payload checksum mismatch')
target = pathlib.Path(sys.argv[2])
target.mkdir(parents=True, exist_ok=True)
with zipfile.ZipFile(io.BytesIO(payload)) as archive:
    for item in archive.infolist():
        path = pathlib.PurePosixPath(item.filename)
        if path.is_absolute() or '..' in path.parts:
            raise SystemExit('Unsafe archive member')
        destination = target.joinpath(*path.parts)
        if not destination.resolve().is_relative_to(target.resolve()):
            raise SystemExit('Extraction path escapes target')
        destination.parent.mkdir(parents=True, exist_ok=True)
        destination.write_bytes(archive.read(item))
print(f'Extracted V4 source to {target.resolve()}')
PY
}
if [[ "${1:-}" == "--help" ]]; then usage; exit 0; fi
if [[ "${1:-}" == "--extract" ]]; then
  [[ $# -eq 2 ]] || { usage; exit 2; }
  extract_payload "$2"
  exit 0
fi
[[ $# -eq 0 ]] || { usage; exit 2; }
[[ $EUID -eq 0 ]] || { echo 'Run the installer as root, or use --extract.' >&2; exit 1; }
command -v systemctl >/dev/null || { echo 'systemd is required. Use --extract for a manual deployment.' >&2; exit 1; }
systemctl show-environment >/dev/null
APP_DIR="${APP_DIR:-/opt/chromex-enrichment-v4}"
APP_PORT="${APP_PORT:-8001}"
[[ "$APP_DIR" =~ ^/opt/[A-Za-z0-9/_-]+$ && "$APP_DIR" != *..* ]] || { echo 'APP_DIR must be a simple /opt path.' >&2; exit 1; }
[[ "$APP_PORT" =~ ^[0-9]+$ ]] && (( APP_PORT >= 1024 && APP_PORT <= 65535 )) || { echo 'Invalid APP_PORT.' >&2; exit 1; }
apt-get update
apt-get install -y python3 python3-venv ca-certificates curl
python3 -c 'import sys; assert sys.version_info >= (3,12), "Python 3.12+ required (Ubuntu 24.04+)"'
id chromex-enrichment >/dev/null 2>&1 || useradd --system --home-dir /var/lib/chromex-enrichment-v4 --shell /usr/sbin/nologin chromex-enrichment
install -d -m 0755 "$APP_DIR" "$APP_DIR/releases"
install -d -o chromex-enrichment -g chromex-enrichment -m 0700 /var/lib/chromex-enrichment-v4
RELEASE="$APP_DIR/releases/$(date -u +%Y%m%dT%H%M%SZ)-$$"
install -d -m 0755 "$RELEASE"
extract_payload "$RELEASE"
python3 -m venv "$RELEASE/venv"
"$RELEASE/venv/bin/pip" install --disable-pip-version-check -r "$RELEASE/requirements-v4-lock.txt"
"$RELEASE/venv/bin/python" -m compileall -q "$RELEASE/enrichment_v4"
chmod -R a+rX "$RELEASE"
ENV_FILE=/etc/chromex-enrichment-v4.env
if [[ ! -e "$ENV_FILE" ]]; then
  python3 - "$ENV_FILE" <<'PY'
import json, os, pathlib, secrets, sys
values = {'ENRICHMENT_API_KEY': os.environ.get('ENRICHMENT_API_KEY') or secrets.token_urlsafe(36),
          'COMPANIES_HOUSE_API_KEY': os.environ.get('COMPANIES_HOUSE_API_KEY', ''),
          'SEARCH_PROVIDER': os.environ.get('SEARCH_PROVIDER', 'local'),
          'SEARXNG_URL': os.environ.get('SEARXNG_URL', 'http://127.0.0.1:8888'),
          'SEARXNG_DAILY_LIMIT': os.environ.get('SEARXNG_DAILY_LIMIT', '100'),
          'SCRAPLING_PYTHON': os.environ.get('SCRAPLING_PYTHON', '/opt/chromex-enrichment-v4/scrapling/bin/python'),
          'SCRAPLING_ENGINE': os.environ.get('SCRAPLING_ENGINE', 'bing'),
          'SCRAPLING_BROWSER_PROFILE': os.environ.get('SCRAPLING_BROWSER_PROFILE', 'native'),
          'SCRAPLING_DAILY_LIMIT': os.environ.get('SCRAPLING_DAILY_LIMIT', '25'),
          'SCRAPLING_SOLVE_CLOUDFLARE': os.environ.get('SCRAPLING_SOLVE_CLOUDFLARE', '0'),
          'EXTERNAL_SEARCH_MONTHLY_LIMIT': os.environ.get('EXTERNAL_SEARCH_MONTHLY_LIMIT', '0'),
          'BRAVE_SEARCH_API_KEY': os.environ.get('BRAVE_SEARCH_API_KEY', ''),
          'CRAWLER_USER_AGENT': os.environ.get('CRAWLER_USER_AGENT', 'ChromeXEnrichment/4.0'),
          'ENRICHMENT_DB': '/var/lib/chromex-enrichment-v4/enrichment.sqlite3'}
if len(values['ENRICHMENT_API_KEY']) < 24 or any('\n' in v or '\r' in v for v in values.values()):
    raise SystemExit('API key must have 24+ characters; config values must be single-line')
path = pathlib.Path(sys.argv[1])
path.write_text(''.join(k + '=' + json.dumps(v) + '\n' for k, v in values.items()))
path.chmod(0o600)
PY
fi
PREVIOUS="$(readlink -f "$APP_DIR/current" || true)"
SERVICE=/etc/systemd/system/chromex-enrichment-v4.service
BACKUP_SERVICE="$(mktemp)"
if [[ -f "$SERVICE" ]]; then cp "$SERVICE" "$BACKUP_SERVICE"; fi
SWITCHED=0
rollback() {
  code=$?
  if (( SWITCHED == 1 )); then
    echo 'V4 startup failed; restoring the previous V4 release.' >&2
    if [[ -n "$PREVIOUS" && -d "$PREVIOUS" ]]; then
      ln -sfn "$PREVIOUS" "$APP_DIR/current.rollback"
      mv -Tf "$APP_DIR/current.rollback" "$APP_DIR/current"
    fi
    if [[ -s "$BACKUP_SERVICE" ]]; then
      cp "$BACKUP_SERVICE" "$SERVICE"
      systemctl daemon-reload
      systemctl restart chromex-enrichment-v4.service || true
    else
      systemctl disable --now chromex-enrichment-v4.service || true
    fi
  fi
  rm -f "$BACKUP_SERVICE"
  exit "$code"
}
trap rollback ERR
# Refuse an unrelated process on the chosen port. Existing V4 is stopped only
# after its replacement is fully prepared.
systemctl stop chromex-enrichment-v4.service 2>/dev/null || true
SWITCHED=1
python3 - "$APP_PORT" <<'PY'
import socket, sys
with socket.socket() as s:
    s.bind(('127.0.0.1', int(sys.argv[1])))
PY
cat > "$SERVICE" <<EOF
[Unit]
Description=ChromeX Enrichment V4 evidence verification
Wants=network-online.target
After=network-online.target

[Service]
Type=simple
User=chromex-enrichment
Group=chromex-enrichment
WorkingDirectory=$APP_DIR/current
EnvironmentFile=$ENV_FILE
Environment=PYTHONDONTWRITEBYTECODE=1
Environment=HOME=/var/lib/chromex-enrichment-v4
ExecStart=$APP_DIR/current/venv/bin/uvicorn enrichment_v4.api:app --host 127.0.0.1 --port $APP_PORT --workers 1 --limit-concurrency 16
Restart=on-failure
RestartSec=10
UMask=0077
NoNewPrivileges=true
PrivateTmp=true
ProtectSystem=strict
ProtectHome=true
ReadWritePaths=/var/lib/chromex-enrichment-v4
RestrictAddressFamilies=AF_INET AF_INET6 AF_UNIX

[Install]
WantedBy=multi-user.target
EOF
chmod 0644 "$SERVICE"
ln -sfn "$RELEASE" "$APP_DIR/current.next"
mv -Tf "$APP_DIR/current.next" "$APP_DIR/current"
systemctl daemon-reload
systemctl enable chromex-enrichment-v4.service
systemctl restart chromex-enrichment-v4.service
READY=0
for attempt in $(seq 1 20); do
  if curl --fail --silent "http://127.0.0.1:$APP_PORT/health" >/dev/null; then READY=1; break; fi
  sleep 1
done
(( READY == 1 ))
trap - ERR
rm -f "$BACKUP_SERVICE"
echo "V4 installed: http://127.0.0.1:$APP_PORT/docs"
echo "Configure API keys in $ENV_FILE, then restart chromex-enrichment-v4."
echo 'Default search is local. Optional SearXNG setup: current/deploy/searxng/setup.sh'
echo 'Optional Scrapling browser discovery: see current/SEARCH-OPTIONS.md'
echo 'Calling integration must honor call_ready and run /call-check immediately before use.'
exit 0
